SELECT worker_id,BOOL_OR(ready AND supports_media AND reported_at>NOW()-INTERVAL '90 seconds' AND vision_model=$1 AND text_model=$2),EXTRACT(EPOCH FROM NOW()-MAX(reported_at)),COUNT(*) FILTER(WHERE ready AND supports_media AND reported_at>NOW()-INTERVAL '90 seconds' AND vision_model=$1 AND text_model=$2) FROM processing_workers GROUP BY worker_id;
